<script setup>
import {computed,onMounted,ref} from 'vue'
import {api} from './api.mjs'
const props=defineProps({boot:Object,disabled:Boolean})
const emit=defineEmits(['refresh','error'])
const status=ref(null),mode=ref('desktop'),enabled=ref(false),source=ref(''),curve=ref(''),curves=ref([]),working=ref(false),message=ref(''),error=ref(''),restart=ref(false),confirmExit=ref(false),stopped=ref(false)
const results=computed(()=>{const list=[...(props.boot?.publishedResults||[])];const current=props.boot?.currentBusiness;if(current?.resultId&&!list.some(v=>v.id===current.resultId))list.unshift({id:current.resultId,name:current.name||'当前业务成果'});return list})
const stamp=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无'
async function run(fn){working.value=true;message.value='';error.value='';try{return await fn()}catch(e){error.value=e.message}finally{working.value=false}}
function apply(value){status.value=value;mode.value=value.settings?.mode||value.mode||'desktop';const forecast=value.settings?.forecast||{};enabled.value=!!forecast.enabled;source.value=forecast.sourceResultId||props.boot?.homeResultId||'';curve.value=forecast.curveId||'';restart.value=!!value.restartRequired||mode.value!==value.mode}
async function load(){await run(async()=>{apply(await api('runtime'));try{const data=await api('lake-curves');curves.value=data.curves||data.items||[]}catch{curves.value=[]}})}
async function save(){await run(async()=>{apply(await api('runtime',{mode:mode.value,forecast:{enabled:enabled.value,sourceResultId:source.value,curveId:curve.value||null,useLatestMainStation:true}}));message.value=restart.value?'设置已保存。重新启动平台后切换运行方式。':'后台设置已保存。';emit('refresh')})}
async function autostart(){await run(async()=>{apply(await api('runtime/autostart',{enabled:!status.value?.settings?.autostart}));message.value=status.value.settings.autostart?'已启用当前Windows账户登录自启。':'已停用登录自启。'})}
async function shutdown(){await run(async()=>{await api('shutdown',{});stopped.value=true;confirmExit.value=false;message.value='平台正在退出，后台任务将停止并保留进度。'})}
onMounted(load)
</script>
<template>
 <section class="panel runtime-panel"><div class="panel-title"><h3>后台运行与自动更新</h3><button :disabled="working||stopped" @click="load">刷新状态</button></div>
  <template v-if="status"><div class="runtime-status"><div><span>当前运行</span><b>{{status.mode==='background'?'后台常驻':'桌面模式'}}</b></div><div><span>登录自启</span><b>{{status.settings?.autostart?'已启用':'未启用'}}</b></div><div><span>服务端口</span><b>{{status.port}}</b></div></div>
  <fieldset :disabled="disabled||working||stopped"><div class="runtime-grid"><label>运行方式<select v-model="mode"><option value="desktop">桌面模式 · 随页面关闭退出</option><option value="background">后台常驻 · 关闭页面后继续运行</option></select></label><div class="runtime-autostart"><span>Windows登录后自动采集</span><button @click="autostart">{{status.settings?.autostart?'停用登录自启':'启用登录自启'}}</button></div></div><p class="muted">运行方式在重新启动后生效；后台常驻时可从页面主动退出平台。</p>
   <div class="runtime-schedule"><div><b>观测采集</b><span>各连接按自己的间隔执行，默认5分钟</span></div><div><b>监测页面</b><span>每60秒刷新已入库资料</span></div><div><b>集合预测</b><span>每日上、下午各获取一次新气象资料</span></div><div><b>报告</b><span>北京时间08:00后生成日报，每周一生成周报</span></div></div>
   <label class="runtime-checkbox"><input v-model="enabled" type="checkbox">自动获取集合气象并运行滚动预测</label><div v-if="enabled" class="runtime-grid"><label>起报状态来源<select v-model="source"><option value="">请选择已有连续成果</option><option v-for="result in results" :key="result.id" :value="result.id">{{result.name||result.displayName||result.id}}</option></select></label><label>湖泊水位—容积曲线<select v-if="curves.length" v-model="curve"><option value="">使用当前配置</option><option v-for="item in curves" :key="item.id" :value="item.id">{{item.name||item.id}}</option></select><input v-else v-model="curve" placeholder="已登记曲线编号；未配置可留空"></label></div><p v-if="enabled" class="muted">起报前自动核对连续状态与气象覆盖；资料不足时保留缺项原因，可在任务中心查看。</p><div class="actions"><button class="primary" :disabled="enabled&&!source" @click="save">保存后台设置</button></div>
  </fieldset><p v-if="restart" class="note warning">已保存的运行方式与当前进程不同，请退出后重新启动平台。</p>
  <details><summary>最近后台状态</summary><p>最近调度：{{stamp(status.lastSchedule?.at)}}<template v-if="status.lastSchedule?.status"> · {{status.lastSchedule.status}}</template></p><p v-if="status.lastSchedule?.message">{{status.lastSchedule.message}}</p><p>集合更新：{{stamp(status.forecastSchedule?.at)}}<template v-if="status.forecastSchedule?.taskId"> · {{status.forecastSchedule.taskId}}</template></p><p class="muted">工作区：{{status.workspace}}</p></details>
  <div class="runtime-exit"><button v-if="!confirmExit" :disabled="working||stopped" @click="confirmExit=true">退出平台</button><template v-else><span>退出将停止后台采集和正在执行的任务，保留已有进度。</span><button :disabled="working" @click="confirmExit=false">取消</button><button :disabled="working" @click="shutdown">确认退出</button></template></div></template>
  <p v-if="working" class="note" role="status">正在更新设置…</p><p v-if="message" class="note" role="status">{{message}}</p><p v-if="error" class="message error" role="alert">{{error}}</p>
 </section>
</template>
<style scoped>
.runtime-panel fieldset{border:0;margin:0;padding:0}.runtime-status{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.runtime-status>div{display:grid;gap:6px;background:var(--surface-alt,#f3f7f8);padding:16px;border-radius:6px}.runtime-status span,.runtime-autostart>span{font-size:12px;color:var(--muted)}.runtime-status b{font-size:18px}.runtime-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:20px 0}.runtime-grid label{display:grid;gap:8px;font-size:13px;color:var(--muted)}.runtime-grid select,.runtime-grid input{width:100%;min-width:0}.runtime-autostart{display:flex;align-items:end;justify-content:space-between;gap:15px}.runtime-schedule{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:24px 0}.runtime-schedule>div{border-left:2px solid var(--line);padding-left:12px;display:grid;gap:5px}.runtime-schedule b{font-size:13px}.runtime-schedule span{font-size:12px;color:var(--muted)}.runtime-checkbox{display:flex;align-items:center;gap:8px}.runtime-checkbox input{width:auto}.runtime-panel details{margin-top:20px}.runtime-panel summary{cursor:pointer;color:var(--muted)}.runtime-exit{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);padding-top:18px;margin-top:22px}.runtime-exit span{font-size:13px;color:var(--muted)}@media(max-width:700px){.runtime-grid,.runtime-schedule{grid-template-columns:1fr}.runtime-status{grid-template-columns:1fr}.runtime-exit{flex-wrap:wrap}.runtime-autostart{align-items:center}}
</style>
